# Figure S6: quantitative stability and exploratory external-rat synthesis.
a<-commandArgs(FALSE);hit<-grep('^--file=',a);sd<-if(length(hit))dirname(sub('^--file=','',a[hit[1]])) else Sys.getenv('PH_RV_SCRIPT_DIR','')
if(!nzchar(sd))stop('Set PH_RV_SCRIPT_DIR when sourcing FigS6.R outside Rscript.')
source(file.path(sd,'00_common_helpers.R'));source(file.path(sd,'13_consensus_stability_helpers.R'));suppressPackageStartupMessages(library(patchwork))
root<-Sys.getenv('PH_RV_PROJECT_ROOT','');if(!nzchar(root))root<-find_project_dir(sd);out<-file.path(root,'outputs','FigS6_outputs');dir.create(out,recursive=TRUE,showWarnings=FALSE)
st<-consensus_stability(root);es<-external_effect_synthesis(root,st)
audit<-st$summary;audit$Label<-sprintf('%d/35; J = %.3f',audit$n_overlap,audit$Jaccard)
pA<-ggplot(audit,aes(Jaccard,factor(Left_out,levels=rev(Left_out))))+geom_segment(aes(x=0,xend=Jaccard,yend=factor(Left_out,levels=rev(Left_out))),color='grey75')+geom_point(color='#D73027',size=2.5)+geom_text(aes(x=1.02,label=Label),hjust=0,size=3)+scale_x_continuous(limits=c(0,1.52),breaks=seq(0,1,.25))+labs(title='A',subtitle='Fixed Shared membership; six-of-seven support',x='Jaccard with the primary panel',y=NULL)+theme_manuscript(10)+theme(plot.title=element_text(hjust=0),plot.subtitle=element_text(size=9))
rr<-st$retention[st$retention$In_final,];rr$Class<-ifelse(rr$Full_support==6,'Exactly 6/8 support','At least 7/8 support')
pB<-ggplot(rr,aes(n_LODO,reorder(Gene,n_LODO),fill=Class))+geom_col(width=.7)+geom_text(aes(label=paste0(n_LODO,'/8')),hjust=-.15,size=2.5)+scale_x_continuous(limits=c(0,9),breaks=0:8)+scale_fill_manual(values=c('Exactly 6/8 support'='#E68613','At least 7/8 support'='#1F78B4'))+labs(title='B',subtitle='Retention is threshold-conditioned',x='Omission runs retaining the gene',y=NULL,fill=NULL)+theme_manuscript(9)+theme(legend.position='bottom',legend.text=element_text(size=8),plot.title=element_text(hjust=0),plot.subtitle=element_text(size=9))+guides(fill=guide_legend(ncol=1))
tt<-st$thresholds;tt$LFC<-factor(tt$LFC,levels=c(.585,1,1.5));tt$Support_required<-factor(tt$Support_required,levels=5:7)
pC<-ggplot(tt,aes(LFC,Support_required,fill=Selected))+geom_tile(color='white',linewidth=1)+geom_text(aes(label=paste0(Selected,' selected\n',Retained_primary,'/35 retained')),size=3.3)+scale_fill_gradient(low='#F1EEF6',high='#E68613')+labs(title='C',subtitle='Fixed 108 Shared candidates; anchor threshold also applied',x='Absolute log2FC threshold',y='Required support out of eight',fill='Selected')+theme_manuscript(10)+theme(panel.border=element_blank(),legend.position='bottom',plot.title=element_text(hjust=0),plot.subtitle=element_text(size=9))
mm<-es$summary[es$summary$Scenario=='Primary_batch1' & es$summary$In_primary & es$summary$Estimable,];mm$Gene<-factor(mm$Gene,levels=rev(mm$Gene[order(mm$Estimate)]))
pD<-ggplot(mm,aes(Estimate,Gene,color=I2))+geom_vline(xintercept=0,linetype=2,color='grey60')+geom_segment(aes(x=Lower,xend=Upper,yend=Gene),linewidth=.5)+geom_point(size=1.7)+scale_color_gradient(low='#1F78B4',high='#D73027',limits=c(0,100))+labs(title='D',subtitle='External rat studies; one MCT batch; modified HK 95% CI',x='Discovery-direction-aligned pooled log2FC',y=NULL,color='I2 (%)')+theme_manuscript(9)+theme(legend.position='bottom',plot.title=element_text(hjust=0),plot.subtitle=element_text(size=9))
fig<-(pA|pB)/(pC|pD);ggsave(file.path(out,'FigureS6.pdf'),fig,width=15,height=12);ggsave(file.path(out,'FigureS6.png'),fig,width=15,height=12,dpi=300)
for(letter in c('A','B','C','D'))ggsave(file.path(out,paste0('FigS6',letter,'.pdf')),get(paste0('p',letter)),width=7.5,height=6)
write.xlsx(list(LODO_selected=st$lodo,Run_summary=st$summary,Gene_stability=st$retention,Threshold_summary=st$thresholds,Effect_synthesis=es$summary,Effect_inputs=es$inputs,Final_Fig5_genes=data.frame(Gene=st$primary),Meta=st$methods,Session=data.frame(Text=capture.output(sessionInfo()))),file.path(out,'FigureS6_source_data.xlsx'),overwrite=TRUE)
writeLines(c('Supplementary Figure S6. Conditional consensus stability and exploratory effect synthesis.','(A) Jaccard indices and retained-primary-gene counts for each omission. The 108-gene Shared candidate universe is fixed; omitting the GSE266139 discovery cohort removes its vote only and does not redefine eligibility. (B) Per-gene retention over eight omission runs. Of the 35 primary genes, 21 with exactly 6/8 support are retained in 2/8 runs, and 14 with at least 7/8 support are retained in all eight. These counts follow arithmetically from the 6/7 threshold and are not independent evidence of biological stability. (C) Prespecified threshold grid conditional on the 108 discovery Shared candidates. Text gives total selected and primary genes retained. The anchor threshold is applied when the discovery cohort is included; no new candidates are admitted. (D) Random-effects estimates aligned to discovery direction for the 35 primary genes, using external rat studies and a single GSE240923 batch. Estimates use fitted SEs, DerSimonian-Laird tau2 and conservative modified Hartung-Knapp t intervals; color denotes conventional Q-based I2. Discovery and human cohorts are excluded. This exploratory synthesis spans different rat models and has only 3–4 available study units; heterogeneity estimates are imprecise. Table S3 reports alternate-batch and estimated-count-cohort omission sensitivities.'),file.path(out,'FigureS6_legend.txt'))
message('Figure S6 completed: ',out)
